-- +goose Up

-- Documents (backend plan 4.11, decision O8): a folder tree per site, one
-- private folder per unit created with the unit, and documents that are
-- uploaded or generated by the server. No versions.

CREATE TABLE folder (
    id                  uuid        NOT NULL,
    org_id              uuid        NOT NULL REFERENCES organization (id),
    site_id             uuid        NOT NULL,
    parent_id           uuid,
    name                text        NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
    -- unit folders are private to the unit's owner and tenant and the managers
    kind                text        NOT NULL DEFAULT 'site' CHECK (kind IN ('site', 'unit')),
    unit_id             uuid,
    visibility_level    text        NOT NULL DEFAULT 'board' CHECK (visibility_level IN ('board', 'owners', 'everyone', 'units')),
    visibility_unit_ids uuid[]      NOT NULL DEFAULT '{}',
    -- created by the system (unit folders and the folders generated documents are filed in)
    is_system           boolean     NOT NULL DEFAULT false,
    system_key          text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    version             int         NOT NULL DEFAULT 1,
    PRIMARY KEY (org_id, id),
    UNIQUE (org_id, site_id, id),
    FOREIGN KEY (org_id, site_id) REFERENCES site (org_id, id),
    FOREIGN KEY (org_id, site_id, parent_id) REFERENCES folder (org_id, site_id, id),
    FOREIGN KEY (org_id, site_id, unit_id) REFERENCES unit (org_id, site_id, id),
    CHECK ((kind = 'unit') = (unit_id IS NOT NULL)),
    CHECK (parent_id IS NULL OR parent_id <> id),
    CHECK (visibility_level = 'units' OR visibility_unit_ids = '{}')
);
CREATE UNIQUE INDEX folder_unit ON folder (org_id, unit_id) WHERE unit_id IS NOT NULL;
CREATE UNIQUE INDEX folder_system_key ON folder (org_id, site_id, system_key) WHERE system_key IS NOT NULL;
CREATE INDEX folder_site ON folder (org_id, site_id, parent_id);
SELECT openbekci_enable_rls('folder');

CREATE TABLE document (
    id                  uuid        NOT NULL,
    org_id              uuid        NOT NULL REFERENCES organization (id),
    site_id             uuid        NOT NULL,
    folder_id           uuid        NOT NULL,
    title               text        NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
    file_id             uuid        NOT NULL,
    -- null: inherits the folder's visibility
    visibility_level    text        CHECK (visibility_level IN ('board', 'owners', 'everyone', 'units')),
    visibility_unit_ids uuid[]      NOT NULL DEFAULT '{}',
    source              text        NOT NULL DEFAULT 'uploaded' CHECK (source IN ('uploaded', 'generated')),
    -- the record a generated document was made from (statement, receipt, minutes ...)
    generated_type      text,
    generated_id        uuid,
    -- a document addressed to one person, readable by them after they moved out (closing statement)
    addressed_person_id uuid,
    uploaded_by         uuid        REFERENCES "user" (id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    version             int         NOT NULL DEFAULT 1,
    PRIMARY KEY (org_id, id),
    UNIQUE (org_id, file_id),
    FOREIGN KEY (org_id, site_id, folder_id) REFERENCES folder (org_id, site_id, id),
    FOREIGN KEY (org_id, file_id) REFERENCES file (org_id, id),
    FOREIGN KEY (org_id, addressed_person_id) REFERENCES person (org_id, id),
    CHECK ((generated_type IS NULL) = (generated_id IS NULL)),
    CHECK (source = 'generated' OR generated_type IS NULL),
    CHECK (visibility_level = 'units' OR visibility_unit_ids = '{}')
);
CREATE INDEX document_folder ON document (org_id, folder_id, id DESC);
CREATE INDEX document_site ON document (org_id, site_id, id DESC);
CREATE INDEX document_addressed ON document (org_id, addressed_person_id) WHERE addressed_person_id IS NOT NULL;
CREATE UNIQUE INDEX document_generated ON document (org_id, generated_type, generated_id) WHERE generated_id IS NOT NULL;
SELECT openbekci_enable_rls('document');

-- A private folder per unit, created with the unit (every creation path, the
-- spreadsheet import included) and renamed with its door number. The id is a
-- random UUID: lists are keyset-paginated by id, so order is stable all the same.
-- +goose StatementBegin
CREATE FUNCTION documents_unit_folder() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO folder (id, org_id, site_id, name, kind, unit_id, visibility_level, is_system)
        VALUES (gen_random_uuid(), NEW.org_id, NEW.site_id, NEW.door_number, 'unit', NEW.id, 'units', true)
        ON CONFLICT DO NOTHING;
    ELSE
        UPDATE folder SET name = NEW.door_number, updated_at = now() WHERE org_id = NEW.org_id AND unit_id = NEW.id AND name <> NEW.door_number;
    END IF;
    RETURN NULL;
END;
$$;
-- +goose StatementEnd
CREATE TRIGGER unit_folder AFTER INSERT OR UPDATE OF door_number ON unit
    FOR EACH ROW EXECUTE FUNCTION documents_unit_folder();

-- Units that exist before this migration get their folder the first time the
-- site's folders are listed (documents.Service.ensureUnitFolders); the
-- migrator cannot write under row-level security without a tenant.

-- +goose Down
DROP TRIGGER unit_folder ON unit;
DROP FUNCTION documents_unit_folder();
DROP TABLE document;
DROP TABLE folder;
